const body = $json.body || $json;
const props = body.export_view?.properties || [];
const citations = body.citations || body.export_view?.session_citations || [];
const booking = body.booking || body.export_view?.visit;
const hard = body.constraints?.hard || {};

const propertyHtml = props.map((p) => {
  const notes = (p.neighborhood_notes || [])
    .map((n) => `<li><strong>${n.topic}:</strong> ${n.text}</li>`)
    .join('');
  return `
  <section style="margin:0 0 24px;padding:16px;border:1px solid #d7e3d4;border-radius:8px;background:#f7faf6">
    <h3 style="margin:0 0 8px;color:#1b4332">${p.society_name}</h3>
    <p style="margin:0 0 8px">₹${Number(p.rent).toLocaleString('en-IN')} · ${p.bedrooms} BHK · ${p.locality}</p>
    <p style="margin:0 0 8px"><strong>Why:</strong> ${p.match_reason || ''}</p>
    <p style="margin:0 0 8px"><strong>Amenities:</strong> ${(p.amenities || []).join(', ')}</p>
    ${notes ? `<ul style="margin:8px 0 0;padding-left:18px">${notes}</ul>` : ''}
  </section>`;
}).join('');

const citationHtml = citations
  .map((c) => `<li><a href="${c.url}">${c.title}</a></li>`)
  .join('');

const prefs = [
  hard.bedrooms ? `${hard.bedrooms} BHK` : null,
  hard.locality || null,
  hard.max_rent ? `≤ ₹${Number(hard.max_rent).toLocaleString('en-IN')}` : null,
  (hard.must_have_amenities || []).join(', ') || null,
].filter(Boolean).join(' · ');

const visitHtml = booking
  ? `<h2>Site visit</h2><p>${booking.date || ''} at ${booking.slot || ''} · Code ${booking.confirmation_code || 'pending'}</p>`
  : '';

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Property Scout Shortlist</title></head>
<body style="font-family:Georgia,serif;color:#1a1a1a;max-width:720px;margin:24px auto;padding:0 16px">
  <h1 style="color:#1b4332">Property Scout Shortlist</h1>
  <p><strong>Recipient:</strong> ${body.recipient_email}</p>
  <h2>Preferences</h2>
  <p>${prefs || 'See attached session constraints.'}</p>
  <h2>Shortlisted properties</h2>
  ${propertyHtml || '<p>No properties in payload.</p>'}
  <h2>Sources</h2>
  <ul>${citationHtml || '<li>No citations attached.</li>'}</ul>
  ${visitHtml}
</body></html>`;

return [{
  json: {
    ...body,
    email_html: html,
    email_subject: 'Your Property Scout shortlist',
    email_text: `Your curated Bengaluru shortlist (${props.length} homes) is ready. Open this email in HTML view for full details.`,
  },
}];
